<script lang="ts" module>
  import type { Snippet } from 'svelte';
  import Circle, { type CircleProps } from './Circle.svelte';
  import type { Without } from '../utils/types.js';

  export type GeoPointPropsWithoutHTML = {
    /**
     * Latitude of the point.
     */
    lat: number;

    /**
     * Longitude of the point.
     */
    long: number;

    /**
     * A bindable reference to the underlying element, which
     * can be a `<circle>` or `<g>` element.
     */
    ref?: Element;

    children?: Snippet<[{ x: number; y: number }]>;
  };

  export type GeoPointProps = Omit<
    GeoPointPropsWithoutHTML & Without<CircleProps, GeoPointPropsWithoutHTML>,
    'x' | 'y'
  >;
</script>

<script lang="ts">
  import Group from './Group.svelte';
  import { getLayerContext } from '../contexts/layer.js';
  import { getGeoContext } from '../contexts/geo.js';
  import { extractLayerProps } from '../utils/attributes.js';

  let {
    lat,
    long,
    ref: refProp = $bindable(),
    children,
    opacity,
    fillOpacity,
    strokeWidth,
    class: className,
    ...restProps
  }: GeoPointProps = $props();

  let ref = $state<Element>();
  $effect.pre(() => {
    refProp = ref;
  });

  const geo = getGeoContext();

  const points = $derived(geo.projection?.([long, lat]) ?? [0, 0]);
  const x = $derived(points[0]);
  const y = $derived(points[1]);

  const layerCtx = getLayerContext();
</script>

{#if layerCtx === 'svg'}
  {#if children}
    <Group {x} {y} opacity={opacity as number} class={className as string} {...extractLayerProps(restProps, 'lc-geo-point-group')}>
      {@render children({ x, y })}
    </Group>
  {:else}
    <Circle cx={x} cy={y} {opacity} {fillOpacity} {strokeWidth} class={className} {...extractLayerProps(restProps, 'lc-geo-point')} />
  {/if}
{/if}

{#if layerCtx === 'canvas'}
  {#if children}
    <!-- TODO: Handle Canvas translation. Consolidate with svg use case above -->
    <!-- <Group {x} {y} {...$$restProps}> -->
    {@render children({ x, y })}
    <!-- </Group> -->
  {:else}
    <Circle cx={x} cy={y} {opacity} {fillOpacity} {strokeWidth} class={className} {...extractLayerProps(restProps, 'lc-geo-point')} />
  {/if}
{/if}
